<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$today=date('Y-m-d');$s=db()->prepare("SELECT o.*,l.name listing_name,l.slug listing_slug,l.location FROM offers o JOIN listings l ON l.id=o.listing_id WHERE o.status='published' AND l.status='published' AND (o.starts_at='' OR o.starts_at<=:now) AND (o.ends_at='' OR o.ends_at>=:today) ORDER BY o.created_at DESC LIMIT 80");$s->execute([':today'=>$today,':now'=>date('Y-m-d H:i:s')]);$offers=$s->fetchAll();$pageTitle='Local offers | '.setting('site_name','MetroGuide');$pageDescription='Explore current offers from local businesses.';include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page"><?php if($f=get_flash()): ?><div class="alert alert-<?= h($f['type']) ?>"><?= h($f['message']) ?></div><?php endif; ?><div class="page-intro"><span class="eyebrow">GOOD THINGS, CLOSE TO HOME</span><h1>Local offers worth knowing.</h1><p>Promotions shared by local businesses. Check the business profile and terms before you visit or purchase.</p></div><?php if($offers): ?><div class="offer-grid"><?php foreach($offers as $o): ?><article class="offer-card"><span class="offer-icon"><i class="fa-solid fa-ticket"></i></span><span class="eyebrow"><?= h($o['location']) ?></span><h2><?= h($o['title']) ?></h2><p><?= h($o['description']) ?></p><?php if($o['promo_code']): ?><div class="promo-code"><small>PROMO CODE</small><strong><?= h($o['promo_code']) ?></strong><button type="button" class="copy-code" data-copy="<?= h($o['promo_code']) ?>" aria-label="Copy promo code"><i class="fa-regular fa-copy"></i></button></div><?php endif; ?><a class="text-link" href="<?= app_path('index.php?listing='.rawurlencode($o['listing_slug'])) ?>"><?= h($o['listing_name']) ?> <i class="fa-solid fa-arrow-right"></i></a><?php if($o['ends_at']): ?><small class="offer-expiry">Offer ends <?= h(format_date($o['ends_at'])) ?></small><?php endif; ?><form method="post" action="<?= app_path('coupon-redeem.php') ?>" class="offer-save-form"><?= csrf_field() ?><input type="hidden" name="offer_id" value="<?= (int)$o['id'] ?>"><button class="button button-outline button-small">Save this offer</button></form></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span><i class="fa-solid fa-tags"></i></span><h3>No active offers right now</h3><p>Check back soon for neighbourhood promotions.</p><a class="button button-primary" href="<?= app_path('index.php') ?>">Explore businesses</a></div><?php endif; ?></main><script>document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>navigator.clipboard?.writeText(b.dataset.copy).then(()=>{b.innerHTML='<i class="fa-solid fa-check"></i>'})));</script><?php include __DIR__.'/includes/footer.php';?>
